UNIT_ZH, UNIT_EN = "廣義線性分類器", "Generalized linear classifiers"
TITLE_ZH = "圖型識別 第四章 KP13：廣義線性分類器（大三）"; TITLE_EN = "Pattern Recognition, Chapter 4, KP13: generalized linear classifiers (undergraduate)"
NOTE_ZH = "教材程度：大學三年級（undergrad）。依講義 lec05-kp13 以 view-from-text-v3 製作：先規劃頁面，每頁以一張原生資訊圖（HTML 設計後轉成原生節點）為主，名詞在同一頁圖內定義。共 9 頁，所有數字皆由程式計算。"
NOTE_EN = "Level: undergraduate (year 3). Made from the lecture lec05-kp13 with view-from-text-v3: pages were planned first and each page is mainly one native infographic (designed in HTML and converted to native nodes), with the terms defined on the same page. 9 pages; every number is computed by program."
def fig(n, alt_zh, alt_en):
    return lambda: native(f"kp13_p{n}", f"lec05-kp13-p{n}", KP.W, KP.H, JD, alt_en if os.environ.get("KP_LANG") == "en" else alt_zh)
P = []
NXT = {1: ("換成座標 (x, x²)", "the new coordinates (x, x²)"), 2: ("回到 x 看是彎的", "the bend seen back in x"), 3: ("XOR 再看一次", "XOR once more"), 4: ("權重怎麼算", "how the weights are computed"), 5: ("同心環", "the concentric rings"), 6: ("多類別", "the multi-class case"), 7: ("投影追蹤的對照", "the comparison with projection pursuit"), 8: ("小練習", "the exercises")}
PREV = {2: ("夾住的類別", "the sandwiched classes"), 3: ("換成座標 (x, x²)", "the new coordinates (x, x²)"), 4: ("回到 x 看是彎的", "the bend seen back in x"), 5: ("XOR 再看一次", "XOR once more"), 6: ("權重怎麼算", "how the weights are computed"), 7: ("同心環", "the concentric rings"), 8: ("多類別", "the multi-class case"), 9: ("投影追蹤的對照", "the comparison with projection pursuit")}
def add(n, lab, title, bridge, notes, alt):
    zh, en = notes
    if n in PREV: zh = f"承接上一頁的「{PREV[n][0]}」。" + zh; en = f"Following the previous page on {PREV[n][1]}. " + en
    if n == 9: zh += "到這裡這個單元就結束了；之後請接著讀下一單元。"; en += " That ends this unit; next, move on to the next unit."
    if n in NXT: zh += f"接下來的下一頁是「{NXT[n][0]}」。"; en += f" Next, the next page covers {NXT[n][1]}."
    P.append(dict(lab=lab, title=title, bridge=bridge, notes=(zh, en), layout="freeform", spec=fig(n, *alt)))
add(1, ("夾住的類別", "Sandwiched classes"),
    ("一維夾住的類別：A 在兩側、B 在中間，任何單一門檻最多分對 7 筆中的 5 筆", "Sandwiched classes in 1-D: A on both sides and B in the middle, so any single threshold gets at most 5 of 7 right"),
    ("資料在原空間用一條線分不開時，怎麼辦？先看最簡單的一維情形。", "What if the data cannot be separated by one line in the original space? Start with the simplest one-dimensional case."),
    ("這是 KP13 的第一頁。先備三件事：線性判別函數（KP01 到 KP03）、平方誤差（KP06）、矩陣乘法與轉置。一維的例子是本講義設計的：類 A 在 x 等於負 3、負 2、2、3，類 B 在負 1、0、1，共 7 筆。程式窮舉所有門檻與方向，最多只能分對 5 筆：例如門檻取 1.5，B 的三點與 A 的 2、3 判對，A 的負 3、負 2 判錯。原因是 A 在 B 的兩側，只看 x 的大小，看不出「在兩邊」這件事（程式計算）。",
     "This is the first page of KP13. Prerequisites: the linear discriminant function (KP01 to KP03), the squared error (KP06) and matrix multiplication with transpose. The one-dimensional example is my own design: class A at x equal to minus 3, minus 2, 2, 3 and class B at minus 1, 0, 1, 7 points in all. A program tries every threshold and direction and at most 5 are right: with the threshold at 1.5, the three B points and the A points at 2 and 3 are right, while the A points at minus 3 and minus 2 are wrong. The reason is that A lies on both sides of B, so the size of x alone cannot say on both sides (computed by program)."),
    ("Seven points on a number line, A at -3,-2,2,3 and B at -1,0,1, with the best single threshold at 1.5: 5 of 7 right, the two A points at -3 and -2 wrong.",) * 2)
add(2, ("換成座標", "New coordinates"),
    ("換成座標 (x, x²)：A 的 y₂ 都不小於 4，B 的都不大於 1，一條水平線 y₂ = 2.5 就分開兩類", "With coordinates (x, x²), A has y₂ ≥ 4 and B has y₂ ≤ 1, so the horizontal line y₂ = 2.5 separates them"),
    ("一維夾住的類別，任何單一門檻最多分對 7 筆中的 5 筆。能不能換一個座標，讓兩類變成「一邊一個」？", "In the sandwiched classes any single threshold gets at most 5 of 7 right. Can a new coordinate put one class on each side?"),
    ("這一頁換座標。特徵映射是用一組函數 fi 把 x 換成新的座標 y 等於 (f1(x), …, fk(x))。這裡取 y 等於 (x, x 平方)，逐點算：A 的 x 為負 3、負 2、2、3，x 平方是 9、4、4、9；B 的 x 為負 1、0、1，x 平方是 1、0、1。A 的 y2 都不小於 4，B 的都不大於 1；一條水平線 y2 等於 2.5 就把兩類分開，也就是新座標裡的一個線性分類器（程式計算）。",
     "This page changes coordinates. A feature mapping uses a set of functions fi to replace x by new coordinates y equal to (f1(x), …, fk(x)). Here take y equal to (x, x squared) and compute point by point: A at x equal to minus 3, minus 2, 2, 3 gives x squared equal to 9, 4, 4, 9; B at minus 1, 0, 1 gives 1, 0, 1. Every A has y2 at least 4 and every B at most 1, so the horizontal line y2 equal to 2.5 separates the two classes, which is a linear classifier in the new coordinates (computed by program)."),
    ("Left: table of x and y2=x^2 for the seven points; right: points lifted to (x, x^2), A above and B below the horizontal line y2 = 2.5.",) * 2)
add(3, ("回到 x 看", "Back in x"),
    ("回到 x 看是彎的：g(x) = −2.5 + x²，邊界在 x = ±1.58，外側是 A、內側是 B", "Back in x the boundary bends: g(x) = −2.5 + x² with boundary at x = ±1.58, A outside and B inside"),
    ("升到 (x, x²) 之後，水平線 y₂ = 2.5 分開了兩類。這條水平線，回到原來的 x 軸看是什麼？", "After lifting to (x, x²), the horizontal line y₂ = 2.5 separates the two classes. What is this line when seen back on the x axis?"),
    ("這一頁回到 x 看。廣義線性分類器：先用固定的非線性函數 fi 升維，再設計普通的線性分類器；線性是指對權重 wi 線性。本例一步一步來：取 f1 等於 x、f2 等於 x 平方，水平線 y2 等於 2.5 對應 w0 等於負 2.5、w1 等於 0、w2 等於 1；所以 g(x) 等於負 2.5 加 x 平方，g 大於 0 判 A、小於 0 判 B；g 等於 0 解得 x 等於正負根號 2.5，約正負 1.58，外側是 A、內側是 B。新空間的一條直線，在原空間是兩個點，也就是邊界在 x 軸上是彎的（程式計算）。",
     "This page looks back in x. A generalized linear classifier lifts with fixed nonlinear functions fi and then designs an ordinary linear classifier; linear means linear in the weights wi. Step by step for this example: take f1 equal to x and f2 equal to x squared; the horizontal line y2 equal to 2.5 corresponds to w0 equal to minus 2.5, w1 equal to 0 and w2 equal to 1; so g(x) equals minus 2.5 plus x squared, with g above 0 called A and below 0 called B; g equal to 0 gives x equal to plus or minus the square root of 2.5, about plus or minus 1.58, with A outside and B inside. One line in the new space is two points in the original space, that is, the boundary bends along the x axis (computed by program)."),
    ("The parabola g(x) = -2.5 + x^2 with the seven points on the x axis; zeros at x = -1.58 and 1.58; g > 0 (A) outside and g < 0 (B) inside.",) * 2)
add(4, ("XOR 再看一次", "XOR once more"),
    ("XOR 再看一次：加一個座標 y₃ = x₁x₂，取 g = x₁ + x₂ − 2y₃ − 0.5，一個平面分開四點", "XOR once more: adding y₃ = x₁x₂ with g = x₁ + x₂ − 2y₃ − 0.5, one plane separates the four points"),
    ("回到 x 看，g(x) = −2.5 + x² 的邊界是彎的，在 x = ±1.58。KP02 的 XOR 要兩條線才分得開，同樣的想法能不能用一個平面做到？", "Back in x, the boundary of g(x) = −2.5 + x² bends, at x = ±1.58, with A outside and B inside. XOR needed two lines in KP02; can this idea do it with one plane?"),
    ("這一頁用同樣的想法再看 XOR。四個點 (0,0)、(0,1)、(1,0)、(1,1)，類別是兩個座標不同為一類，也就是 (0,1) 與 (1,0) 為 A。加上一個座標 y3 等於 x1 乘 x2；取 g 等於 x1 加 x2 減 2 y3 減 0.5，逐點代入：(0,0) 為負 0.5、(0,1) 為正 0.5、(1,0) 為正 0.5、(1,1) 為負 0.5，四點用一個平面分開。KP02 是用兩條線再合成，這裡是一個固定的映射加一個平面（程式計算）。",
     "This page looks at XOR again with the same idea. The four points are (0,0), (0,1), (1,0), (1,1), and a class means the two coordinates differ, that is, (0,1) and (1,0) are A. Add the coordinate y3 equal to x1 times x2; take g equal to x1 plus x2 minus 2 y3 minus 0.5 and substitute point by point: (0,0) gives minus 0.5, (0,1) gives plus 0.5, (1,0) gives plus 0.5 and (1,1) gives minus 0.5, so one plane separates the four points. KP02 combined two lines; here it is one fixed mapping plus one plane (computed by program)."),
    ("XOR points are not separable in the plane; with y3 = x1x2 the side view (x1+x2, y3) is separated by one line; g values -0.5, +0.5, +0.5, -0.5 for (0,0),(0,1),(1,0),(1,1).",) * 2)
add(5, ("權重怎麼算", "Computing weights"),
    ("權重用正規方程算：w = (ΦᵀΦ)⁻¹Φᵀt = (−0.810, 0, 0.238)，七筆全對", "The weights come from the normal equation: w = (ΦᵀΦ)⁻¹Φᵀt = (−0.810, 0, 0.238), all seven right"),
    ("XOR 再看一次：加一個座標 y₃ = x₁x₂，一個平面分開四點。映射是固定的，那三個權重 w₀、w₁、w₂ 怎麼算，而不是用眼睛猜？", "Once more on XOR: adding y₃ = x₁x₂ lets one plane separate the four points. The mapping is fixed, so how are the weights w₀, w₁, w₂ computed rather than guessed by eye?"),
    ("這一頁算權重。正規方程是讓 Φ w 與目標 t 的平方誤差最小的解：w 等於 (Φ 轉置 Φ) 的反矩陣乘 Φ 轉置 t。Φ 的每一列是一個樣本的 (1, f1, …, fk)，本例是 (1, x, x 平方)；t 中 A 為正 1、B 為負 1。第 1 節的七個點解得 w 等於 (負 0.810, 0, 0.238)；七個 g 是 1.333、0.143、0.143、1.333、負 0.571、負 0.810、負 0.571，正負都和目標相同，七筆全對（程式計算）。它和第 3 頁手設的 (負 2.5, 0, 1) 不同；兩組都分對，最小二乘追求的是平方誤差最小，不是邊界離哪裡最遠。",
     "This page computes the weights. The normal equation is the solution that minimizes the squared error between Φ w and the target t: w equals the inverse of (Φ transpose Φ) times Φ transpose t. Each row of Φ is (1, f1, …, fk) of one sample, here (1, x, x squared); in t, A is plus 1 and B is minus 1. The seven points of section 1 give w equal to (minus 0.810, 0, 0.238); the seven g values are 1.333, 0.143, 0.143, 1.333, minus 0.571, minus 0.810, minus 0.571, whose signs all match the targets, so all seven are right (computed by program). It differs from the hand-set (minus 2.5, 0, 1) of page 3; both classify everything right, and least squares aims at the smallest squared error, not at the largest distance of the boundary."),
    ("Normal equation w = (Phi^T Phi)^-1 Phi^T t gives w = (-0.810, 0, 0.238); g at the seven points 1.333, 0.143, 0.143, 1.333, -0.571, -0.810, -0.571, all with the sign of the target.",) * 2)
add(6, ("同心環", "Concentric rings"),
    ("同心環：直線特徵只對 102 筆（51%），二次特徵對 199 筆（99.5%），決策圓半徑約 1.71", "Concentric rings: 51% with linear features, 99.5% with quadratic, decision circle radius 1.71"),
    ("正規方程把七個點全分對。一維的例子手算得動，換到二維的同心環，兩種特徵各能分對多少？", "The normal equation got all seven points right. A one-dimensional example can be done by hand; on two-dimensional concentric rings, how many does each feature set get right?"),
    ("這一頁換到二維的同心環，用程式實驗。實驗設定是本講義設計、可重現：兩類各 100 點，角度在 0 到 2π 均勻取，半徑 A 類取常態平均 1.0、標準差 0.15，B 類取平均 2.2、標準差 0.2，亂數種子 0；目標 A 為正 1、B 為負 1，兩種特徵都用最小二乘求權重。直線特徵 [1, x1, x2] 3 個，答對 102 筆，51%，等於亂猜；二次特徵 6 個，答對 199 筆，99.5%。二次特徵的 g 等於 0 在原空間是半徑約 1.71 的圓，落在兩圈（平均半徑約 0.98 與 2.19）之間。這是同一份訓練資料上的正確率，只說明能不能表示，不是泛化能力。二次特徵的個數是 l 乘 l 加 3 除以 2：l 為 2、10、100 時是 5、65、5150（程式計算）。",
     "This page moves to two-dimensional concentric rings and uses a program. The setup is my own design and reproducible: 100 points per class, the angle uniform over 0 to 2π, the radius normal with mean 1.0 and standard deviation 0.15 for A and mean 2.2 and standard deviation 0.2 for B, random seed 0; targets are plus 1 for A and minus 1 for B, and both feature sets use least squares. The linear features [1, x1, x2], 3 of them, get 102 right, 51%, which is guessing; the quadratic features, 6 of them, get 199 right, 99.5%. For the quadratic features g equal to 0 is a circle of radius about 1.71 in the original space, between the two rings, whose mean radii are about 0.98 and 2.19. This is accuracy on the same training data, so it only shows what can be represented, not generalization. The number of quadratic features is l times l plus 3 over 2: 5, 65, 5150 for l equal to 2, 10, 100 (computed by program)."),
    ("Two concentric rings of 100 points each with the decision circle of radius 1.71; linear features 102 of 200 (51%), quadratic features 199 of 200 (99.5%); number of quadratic features 5, 65, 5150 for l = 2, 10, 100.",) * 2)
add(7, ("多類別", "Multi-class"),
    ("多類別：三個權重向量取 g 最大的類，九點全對；只用 (1, x) 只對 7 筆", "Multi-class: three weight vectors and the class with the largest g get all nine points right; only (1, x) gets 7"),
    ("同心環上，直線特徵只對 102 筆，二次特徵對 199 筆。類別不只兩個的時候，要怎麼做？", "On the concentric rings, linear features got 102 right and quadratic features 199. What do we do when there are more than two classes?"),
    ("這一頁處理多類別：M 類就設計 M 個權重向量，選 wr 轉置 y 加 wr0 最大的類。例子是本講義設計的：一維九點，x 等於負 3、負 2.5、負 2 為類 1，負 0.5、0、0.5 為類 2，2、2.5、3 為類 3。目標用 one-hot，也就是類 r 的目標向量只有第 r 個是 1；特徵 (1, x, x 平方)，最小二乘解三組權重，九筆全對。只用 (1, x) 只對 7 筆，中間類只剩 x 等於 0 判對，該點三個 g 並列為 1/3，取中間類（程式計算）。",
     "This page handles several classes: M classes need M weight vectors, and the class with the largest wr transpose y plus wr0 is chosen. The example is my own design: nine points in one dimension, with x equal to minus 3, minus 2.5, minus 2 in class 1, minus 0.5, 0, 0.5 in class 2 and 2, 2.5, 3 in class 3. The targets are one-hot, that is, the target vector of class r has only its r-th entry equal to 1; with features (1, x, x squared) least squares solves three weight sets and all nine are right. With only (1, x) just 7 are right, and the middle class keeps only x equal to 0, where the three g tie at 1/3 and the middle class is taken (computed by program)."),
    ("Three quadratic g curves with the class of the highest curve shown as a strip and nine sample points; all 9 right with (1, x, x^2), 7 right with only (1, x).",) * 2)
add(8, ("投影追蹤的對照", "Projection pursuit"),
    ("對照投影追蹤：w 加倍後廣義線性的 g 剛好加倍，投影追蹤卻是 f(2) = 0.881、不是 2f(1) = 1.462", "Projection pursuit differs: doubling w doubles g for generalized linear, but f(2) = 0.881 is not 2f(1) = 1.462"),
    ("三個權重向量取 g 最大的類，九點全對。廣義線性分類器的映射是固定的，和另一種把方向也學進去的做法差在哪裡？", "Three weight vectors with the largest g got all nine points right. The mapping of a generalized linear classifier is fixed; how does it differ from an approach that also learns the direction?"),
    ("這一頁對照投影追蹤：g(x) 等於 fi 括號 wi 轉置 x 的總和；fi 的引數是 x 在方向 wi 上的投影，方向與函數要一起最佳化。加倍測試：把 w 加倍，廣義線性的 g 剛好加倍；投影追蹤（f 為 sigmoid、輸入 1、w 等於 1）是 f(2) 等於 0.881，不是 2 f(1) 等於 1.462，所以它對 w 不是線性的，要用兩階段交替最佳化。若把 fi 事先固定為 sigmoid，就是單隱藏層神經網路，實務上已被多層感知器取代。怎麼記：廣義線性等於固定的映射加可學的線性層；多層感知器等於可學的映射加可學的線性層（程式計算）。",
     "This page compares projection pursuit: g(x) is the sum of fi of wi transpose x; the argument of fi is the projection of x on the direction wi, and the directions and functions are optimized together. In the doubling test, doubling w exactly doubles g for the generalized linear classifier; for projection pursuit (f a sigmoid, input 1, w equal to 1) f(2) equals 0.881, not 2 f(1) equal to 1.462, so it is not linear in w and needs two-stage alternating optimization. If fi is fixed in advance as a sigmoid, it is a one-hidden-layer neural network, which multilayer perceptrons have replaced in practice. To remember: generalized linear is a fixed mapping plus a learnable linear layer; a multilayer perceptron is a learnable mapping plus a learnable linear layer (computed by program)."),
    ("Block diagrams: generalized linear (x, fixed f_i, learned w, g) versus projection pursuit (x, learned direction w_i, fitted f_i, g); doubling test: g doubles for generalized linear, but sigmoid(2) = 0.881 is not 2*sigmoid(1) = 1.462.",) * 2)
add(9, ("小練習", "Exercises"),
    ("兩題小練習：(1,1) 屬 B，(3,0) 與 (0,−2.5) 屬 A；g = 0 是半徑 2 的圓", "Two exercises: (1,1) is B, (3,0) and (0,−2.5) are A; g = 0 is a circle of radius 2"),
    ("對照投影追蹤，w 加倍後廣義線性的 g 剛好加倍，投影追蹤不會。用特徵 y = (x₁², x₂²) 的廣義線性分類器判一次，各點屬哪一類？", "In the comparison with projection pursuit doubling w exactly doubles g for generalized linear classifiers. With features y = (x₁², x₂²), which class does each point belong to?"),
    ("兩題小練習，特徵 y 等於 (x1 平方, x2 平方)，g 等於 y1 加 y2 減 4，g 大於 0 為 A。題 1：判 (1,1)、(3,0)、(0,負 2.5) 各屬哪一類？(1,1)：1 加 1 減 4 等於負 2，屬 B；(3,0)：9 加 0 減 4 等於 5，屬 A；(0,負 2.5)：0 加 6.25 減 4 等於 2.25，屬 A。題 2：g 等於 0 在 x 平面上是什麼圖形？g 等於 0 即 x1 平方加 x2 平方等於 4，是半徑 2 的圓：在 y 空間是一條直線，在 x 空間是彎的（程式計算）。",
     "Two exercises with features y equal to (x1 squared, x2 squared) and g equal to y1 plus y2 minus 4, where g above 0 is A. Q1: which class are (1,1), (3,0), (0, minus 2.5)? For (1,1): 1 plus 1 minus 4 equals minus 2, class B; for (3,0): 9 plus 0 minus 4 equals 5, class A; for (0, minus 2.5): 0 plus 6.25 minus 4 equals 2.25, class A. Q2: what shape is g equal to 0 in the x plane? g equal to 0 means x1 squared plus x2 squared equal to 4, a circle of radius 2: a straight line in y space and bent in x space (computed by program)."),
    ("Exercise 1: (1,1) gives g=-2, class B; (3,0) gives 5, class A; (0,-2.5) gives 2.25, class A. Exercise 2: g=0 is x1^2+x2^2=4, a circle of radius 2.",) * 2)
PAGES = P
